import {apiUrl} from '/api-url.js';
import {ACADEMY_MAP} from '/shared/arena-layout.js';
import {showHeroPreview,bindHeroDetails} from '/hero-picker.js';
import {isVersus,teamSize,modeLabel,versusModes} from '../shared/modes.js';
import {createHeroSlideshow} from '../shared/hero-slideshow.js';
import {fitViewport,enterMobileLandscape,bindLandscapeNotice} from '/viewport.js';
import {createTrialRoom,confirmTrialHero,tickTrialSelection,launchTrial,trialChat,parseTrialQuestions} from './shared/trial-flow.js';
import {heroes} from './shared/heroes.js';
import {createMatch,step,botInput,scores,result as matchResult} from './shared/engine.js';
import {pumpQuizzes,answerQuiz,publicQuiz} from './shared/quizzes.js';
import {makeSocket} from './transport.js';
import {makeJoystick} from './joystick.js';
import {createArena} from './arena-3d.js';
import QRCode from '/vendor/qrcode.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),asset=(h,kind='portraits')=>'/assets/mila/'+kind+'/'+h+'.webp';
const trialMode=true;
const initialMode=new URLSearchParams(location.search).get('mode');
let playMode=isVersus(initialMode)?initialMode:'duel';
const isHost=document.body.dataset.page==='mc',screenIDs=['entry','host','selection','waiting','battle','result'];
let roomInfo=null,auth=null,socket=null,room=null,match=null,selected='luna',quiz=null,quizAnswered=false,quizClosed=0,phase=null,practice=false,practiceBank=[],cameraMode=isHost?'overview':'follow',cameraSide=null;
let joystick={forward:0,right:0},keys=new Set(),pressed=new Set(),toastTimer,online=false,qrCode=null;
const arena=createArena($('#arena'));
const titles={entry:'HỌC VIỆN PHÉP THUẬT',host:'BẢNG ĐIỀU KHIỂN QUẢN TRÒ',selection:'CHỌN NGƯỜI BẠN ĐỒNG HÀNH',waiting:'SẴN SÀNG VÀO ĐẤU TRƯỜNG',result:'VINH DANH NHÀ VÔ ĐỊCH'};
const clock=n=>{n=Math.max(0,Math.ceil(n));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');};
const hero=id=>heroes.find(h=>h.id===id)||heroes[1];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function run(fn){return async e=>{try{await fn(e);}catch(err){toast(err.message||String(err));}};}
function bind(id,fn){$('#'+id).addEventListener('click',run(fn));}
const slideshow=createHeroSlideshow($('#slideArt'),$('#slideCaption'),heroes,id=>asset(id,'sheets'));
function show(v){if(v==='waiting'&&$('#waiting').hidden)slideshow.start(performance.now());for(const id of screenIDs)$('#'+id).hidden=id!==v;if(isHost)$('#battle').hidden=false;$('#pageTitle').textContent=titles[v]||'HỌC VIỆN PHÉP THUẬT';document.body.classList.toggle('in-battle',v==='battle');checkOrientation();}
function modal(content){$('#modalBody').innerHTML=content;$('#modal').hidden=false;}
function closeModal(){$('#modal').hidden=true;}
bind('modalClose',closeModal);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal();});
function detail(id){$('#detailArt').src=asset(id,'sheets');$('#detailArt').alt=hero(id).name+' và chiêu thức';$('#heroDetail').hidden=false;keys.clear();pressed.clear();}
bindHeroDetails(detail);
$('#heroDetail').addEventListener('pointerdown',()=>$('#heroDetail').hidden=true);
window.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#heroDetail').hidden=true;closeModal();}});
async function api(path,body,method){const r=await fetch(apiUrl(path),{method:method||(body?'POST':'GET'),headers:{'Content-Type':'application/json',...(auth?{Authorization:'Bearer '+auth.token}:{})},...(body?{body:JSON.stringify(body)}:{})});let v;try{v=await r.json();}catch{throw Error('Máy chủ chưa sẵn sàng. Thử lại sau ít phút.');}if(!r.ok)throw Error(v.error||'Không kết nối được.');return v;}
async function session(name,host=false){let old;try{old=JSON.parse(localStorage.getItem(host?'mila-host':'mila-player')||'null');}catch{}auth=await api(host?'/api/host':'/api/guest',{nickname:name,resumeToken:old?.name===name||host?old?.token:undefined});localStorage.setItem(host?'mila-host':'mila-player',JSON.stringify(auth));return auth;}
function emit(event,data={}){if(!socket)throw Error('Hãy vào phòng trước.');return new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Kết nối chậm. Hãy thử lại.')),12000);socket.emit(event,data,r=>{clearTimeout(timeout);if(r?.error)reject(Error(r.error));else resolve(r||{});});});}
async function connect(code,team=0,spectator=isHost,rosterId){let didJoin=false;socket?.disconnect();socket=makeSocket({auth:{token:auth.token}});await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Không kết nối được máy chủ.')),12000);socket.on('connect',()=>{clearTimeout(timeout);online=true;$('#connection').textContent='● Đã kết nối';if(didJoin)socket.emit('join',{code,team,spectator,rosterId},r=>{if(r?.room)updateRoom(r.room);if(r?.error)toast(r.error);});resolve();});socket.on('connect_error',e=>{clearTimeout(timeout);reject(e);});});
 socket.on('room',r=>updateRoom(r));socket.on('match',m=>updateMatch(m));socket.on('question',q=>openQuiz(q));socket.on('chat',c=>{teamChat.push(c);teamChat=teamChat.slice(-30);renderChat();});socket.on('disconnect',()=>{online=false;$('#connection').textContent='◌ Đang kết nối lại…';keys.clear();pressed.clear();});
 const joined=await emit('join',{code,team,spectator,rosterId});didJoin=true;updateRoom(joined.room);sessionStorage.setItem(isHost?'mila-host-room':'mila-player-room',JSON.stringify({code,team,spectator,mode:joined.room.mode}));
}
function emblem(i){const key=room?.emblems?.[i]||['phoenix','cat','deer','dragon'][i];return `<img class="team-emblem" src="/assets/mila/teams/${key}.webp" alt="Biểu tượng đội">`;}
function own(){return room?.players.find(p=>p.id===auth?.id);}
function nextPair(){if(!room)return[0,1];if(isVersus(room.mode))return[0,1];if(room.phase==='lobby')return[room.seed[0],room.seed[3]];return room.pair;}
function updateRoom(r){if(!r)return;const before=room?.phase;room=r;if(before!==r.phase&&['battle','result','finished'].includes(r.phase)){$('#heroDetail').hidden=true;$('#quiz').hidden=true;quiz=null;}if(isHost){renderHost();if(room.phase==='battle'||room.phase==='result'||room.phase==='finished'){if(match)updateMatch(match);}return;}
 const p=own();if(room.phase==='select'&&room.pair.includes(p?.team)&&p?.approved){if(before!=='select'){selected='luna';buildHeroGrid();}show('selection');renderSelection();}
 else if(['result','finished'].includes(room.phase)&&room.results.length){renderResult();}
 else if(room.phase==='battle'){if(room.pair.includes(p?.team)&&p?.approved){$('#battle').classList.remove('spectator');arena.camera(cameraMode==='third'?'third':'follow');}else{$('#battle').classList.add('spectator');arena.camera('overview');}show('battle');}
 else {show('waiting');renderWaiting();}phase=room.phase;checkOrientation();
}
let hudAt=0;
function updateMatch(m){match=m;const p=m.players.find(p=>p.id===auth?.id);arena.snapshot({...m,paused:room?.paused},auth?.id);if(performance.now()-hudAt<100)return;hudAt=performance.now();
 const pair=room?.pair||m.pair,ts=room?.teams||['Hỏa Phượng','Nguyệt Ảnh','Lục Diệp','Thiên Vũ'];const ss=scores(m);$('#battleTeamA').textContent=ts[pair[0]];$('#battleTeamB').textContent=ts[pair[1]];$('#killScore').textContent=ss.map(s=>s.kills).join(' — ');$('#matchTime').textContent=clock(m.duration-m.time);$('#pauseBanner').hidden=!room?.paused;
 const side=ss.find(s=>s.team===(p?.team??pair[0]));$('#knowledgeValue').textContent=side?.knowledge||0;$('#combatValue').textContent=side?.kills||0;
 if(p){const h=hero(p.hero);$('#hudPortrait').src=asset(h.id);$('#hudName').textContent=p.name;$('#hudLevel').textContent=p.level;$('#hpFill').style.width=Math.max(0,p.hp/h.hp*100)+'%';$('#hpText').textContent=Math.ceil(Math.max(0,p.hp))+' / '+h.hp;$('#xpFill').style.width=(p.level/10*100)+'%';$('#wallet').textContent=p.wallet;
 for(let k=1;k<=3;k++)$('#s'+k).src='/assets/mila/skills/'+p.hero+'-'+k+'.webp';$$('[data-skill]').forEach(b=>{const k=+b.dataset.skill;b.querySelector('i').textContent=p.cd[k]>0?Math.ceil(p.cd[k]):k===3&&!p.ultimate?'♙':'';b.classList.toggle('locked',k===3&&!p.ultimate);});$('#ultHint').textContent=p.ultimate?'Chiêu cuối sẵn sàng':'Trả lời đúng để mở';$('#respawn').hidden=!p.dead;$('#respawn b').textContent=Math.ceil(p.dead||0);}
 $('#miniDots').innerHTML=m.players.filter(p=>!p.dead).map(q=>`<i class="mini-dot ${q.team!==p?.team?'enemy':''} ${q.id===auth?.id?'me':''}" style="left:${(.5+q.x/ACADEMY_MAP.width)*100}%;top:${(.5+q.z/ACADEMY_MAP.depth)*100}%"></i>`).join('');
 if(isHost)updateHostScores();if(quiz&&!quizAnswered&&m.time-quiz.at>=10)finishQuizTimeout();
}
async function findRoom(){const code=$('#roomCode').value.trim();if(!/^\d{6}$/.test(code))throw Error('Nhập đủ mã phòng 6 số.');const info=await api('/api/room-info/'+code);roomInfo=info;$('#joinTeam').innerHTML=info.teams.map((s,i)=>`<option value="${i}">${esc(s)}</option>`).join('');renderRosterChoices();toast('Đã tìm thấy '+info.title);return info;}
function renderRosterChoices(){const rows=roomInfo?.roster?.filter(r=>r.team===+$('#joinTeam').value&&!r.claimedBy)||[];$('#rosterLabel').hidden=!rows.length;$('#rosterSlot').innerHTML='<option value="">Dùng biệt danh của tôi</option>'+rows.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');}
$('#joinTeam').addEventListener('change',renderRosterChoices);
bind('findRoom',findRoom);$('#roomCode').value=new URLSearchParams(location.search).get('room')||'';
$('#joinForm').addEventListener('submit',run(async e=>{e.preventDefault();if(trialMode){$('#practice').click();return;}const name=$('#nickname').value.trim();if(!name)throw Error('Nhập biệt danh của bạn.');const team=+$('#joinTeam').value,slot=$('#rosterSlot').value;await findRoom();$('#joinTeam').value=String(team);renderRosterChoices();$('#rosterSlot').value=slot;await session(name);await connect($('#roomCode').value.trim(),team,false,$('#rosterSlot').value||undefined);toast(isVersus(room?.mode)?'Đã vào phòng · Đủ người sẽ chọn tướng!':'Đã vào phòng. Chờ quản trò duyệt nhé!');}));
$('#nickname').value=(()=>{try{return JSON.parse(localStorage.getItem('mila-player')||'null')?.name||'';}catch{return'';}})();
function buildHeroGrid(){$('#heroGrid').innerHTML=heroes.map(h=>`<button class="hero-card" data-hero="${h.id}"><img src="${asset(h.id)}" alt="${h.name}" draggable="false"><b>${h.name}</b><small>${h.role}</small></button>`).join('');
 for(const b of $$('.hero-card')){let timer=null,held=false,start=null;const clear=()=>{clearTimeout(timer);timer=null;b.classList.remove('holding');};b.addEventListener('pointerdown',e=>{if(b.classList.contains('taken'))return;held=false;b.classList.add('holding');start={x:e.clientX,y:e.clientY};b.setPointerCapture(e.pointerId);b.classList.add('holding');timer=setTimeout(()=>{held=true;clear();detail(b.dataset.hero);},3000);});b.addEventListener('pointermove',e=>{if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>18)clear();});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,clear);b.addEventListener('contextmenu',e=>e.preventDefault());b.addEventListener('click',()=>{if(held){held=false;return;}if(b.classList.contains('taken'))return;selected=b.dataset.hero;renderSelection();});b.addEventListener('keydown',e=>{if(e.key==='F1'){e.preventDefault();detail(b.dataset.hero);}});}}
function renderSelection(){const p=own(),h=hero(p?.heroReady?p.hero:selected),team=p?.team;
 showHeroPreview(h);
 $('#previewSkills').innerHTML=[1,2,3].map(k=>`<img src="/assets/mila/skills/${h.id}-${k}.webp" alt="${esc(k===1?h.skill:k===2?h.second:'Chiêu cuối')}">`).join('');
 for(const b of $$('.hero-card')){const taken=room.players.some(q=>q.team===team&&q.id!==p?.id&&q.heroReady&&q.hero===b.dataset.hero);b.classList.toggle('chosen',b.dataset.hero===h.id);b.classList.toggle('taken',taken);b.setAttribute('aria-disabled',taken?'true':'false');}
 $('#teammates').innerHTML='<h3>ĐỒNG ĐỘI</h3>'+room.players.filter(q=>q.team===team).map(q=>`<div class="teammate"><img src="${asset(q.hero||'luna')}" alt=""><div>${esc(q.name)}<small>${q.heroReady?'✓ '+hero(q.hero).name:'Đang chọn…'}</small></div></div>`).join('');$('#confirmHero').disabled=!!p?.heroReady;$('#confirmHero').textContent=p?.heroReady?'✓ ĐÃ CHỐT':'✦ CHỐT NHÂN VẬT';$('#selectionStatus').textContent=p?.heroReady?'Đang chờ đồng đội chọn xong':'Hết giờ sẽ tự chọn tướng còn trống';
}
bind('confirmHero',async()=>{if(practice){if(Date.now()>=room.selectionEnds){tickTrialSelection(room);updateRoom(room);return;}confirmTrialHero(room,selected);$('#heroDetail').hidden=true;updateRoom(room);return;}const r=await emit('selectHero',{hero:selected});if(r.room)updateRoom(r.room);});
function waitTeam(t){return`<h2>${emblem(t)} ${esc(room.teams[t])}</h2>`+room.players.filter(p=>p.team===t).map(p=>`<div class="waiting-member"><img src="${asset(p.hero||'luna')}" alt="${p.hero?hero(p.hero).name:''}"><div><b>${esc(p.name)}</b><small>${!p.approved?'Chờ duyệt':p.heroReady?'✓ '+hero(p.hero).name:'Đã vào phòng'}</small></div></div>`).join('');}
function renderWaiting(){if(practice){$('.waiting-title').textContent='HAI ĐỘI ĐÃ SẴN SÀNG · '+modeLabel(playMode);$('#waitingA').innerHTML=waitTeam(0);$('#waitingB').innerHTML=waitTeam(1);$('#waitingMessage').innerHTML='Đã chốt đủ tướng. Trong bản thử, bạn bấm bắt đầu thay quản trò.<br><button id="launchPractice" class="primary">▷ BẮT ĐẦU TRẬN</button><br><button id="trialReselect">Chọn lại tướng</button>';$('#launchPractice').onclick=run(launchPractice);$('#trialReselect').onclick=run(startPractice);return;}if(isVersus(room.mode)){$('.waiting-title').textContent='ĐẤU PHÉP THUẬT · '+modeLabel(room.mode);$('#waitingA').innerHTML=waitTeam(0);$('#waitingB').innerHTML=waitTeam(1);$('#waitingMessage').innerHTML='Mã phòng: <b>'+esc(room.code)+'</b><br>Đã có '+room.players.length+'/'+(teamSize(room.mode)*2)+' người. Đủ người sẽ tự mở chọn tướng.<br><button id=duelInvite>Sao chép link mời</button>';$('#duelInvite').onclick=run(async()=>{await navigator.clipboard.writeText(location.origin+'/player.html?mode='+room.mode+'&room='+room.code);toast('Đã sao chép link mời');});return;}$('.waiting-title').textContent=(room.phase==='ready'?'Hai đội đã sẵn sàng':'Hẹn nhau tại học viện')+' · '+modeLabel(room.mode);const pair=nextPair();$('#waitingA').innerHTML=waitTeam(pair[0]);$('#waitingB').innerHTML=waitTeam(pair[1]);const p=own();$('#waitingMessage').textContent=!p?.approved?'Chờ quản trò duyệt vào phòng…':room.phase==='ready'?'Hai đội đã chọn xong · Đợi quản trò bắt đầu trận…':!pair.includes(p.team)?'Đội bạn chờ vòng tiếp theo · Có thể xem trận đang đấu':'Đợi quản trò mở chọn tướng…';}
$('#slideArt').addEventListener('click',()=>detail(slideshow.hero.id));
function renderHost(){show('host');const pair=nextPair();$('#hostCode').textContent=room.code;$('#battleTeamA').textContent=room.teams[pair[0]];$('#battleTeamB').textContent=room.teams[pair[1]];$('#connection').textContent=(online?'● Đã kết nối · ':'◌ Kết nối lại · ')+room.code;$('#hostTeamA').textContent=room.teams[pair[0]];$('#hostTeamB').textContent=room.teams[pair[1]];$$('[data-camera]').forEach(b=>{if(b.dataset.camera==='teamA')b.textContent='Đội '+room.teams[pair[0]];if(b.dataset.camera==='teamB')b.textContent='Đội '+room.teams[pair[1]];});$('#playerCount').textContent=room.players.length+'/20 người';
 const editors=$('#teamEditors');if(!editors.children.length)editors.innerHTML=[...pair,...[0,1,2,3].filter(i=>!pair.includes(i))].map((i,j)=>{const s=room.teams[i];return `<div class="team-editor" ${j>1?'hidden':''}>${emblem(i)}<div><input data-team-name="${i}" value="${esc(s)}" maxlength="24" aria-label="Tên đội ${i+1}"><div class="member-chips" data-chips="${i}"></div></div></div>`;}).join('')+'<button class="more-team" id="moreTeams">＋ Hai đội còn lại</button>';
 const extra=$('#moreTeams');if(extra)extra.onclick=()=>{editors.querySelectorAll('.team-editor').forEach(e=>e.hidden=false);extra.hidden=true;};
 for(let i=0;i<4;i++){const input=$(`[data-team-name="${i}"]`);if(document.activeElement!==input)input.value=room.teams[i];$(`[data-chips="${i}"]`).innerHTML=room.players.filter(p=>p.team===i).map(p=>`<span class="member-chip ${p.approved?'online':''}">${esc(p.name)}</span>`).join('')||'<small>Chưa có thành viên</small>';}
 const start=$('#hostStart');start.textContent=room.phase==='ready'?'▷ BẮT ĐẦU TRẬN':room.phase==='select'?'◷ ĐANG CHỌN TƯỚNG':room.phase==='battle'?'✦ ĐANG THI ĐẤU':room.phase==='finished'?'✦ GIẢI ĐÃ KẾT THÚC':room.phase==='result'?'▷ MỞ VÒNG TIẾP THEO':'▷ MỞ CHỌN TƯỚNG';start.disabled=['battle','select','finished'].includes(room.phase);$('#pause').disabled=room.phase!=='battle';$('#pause').textContent=room.paused?'▷ Tiếp tục':'Ⅱ Tạm dừng';$('#endMatch').disabled=room.phase!=='battle';
 $('#hostHint').textContent=room.phase==='ready'?'Các đội đã chọn xong. Bấm BẮT ĐẦU TRẬN để vào đấu trường.':room.phase==='select'?'Học sinh có 20 giây chọn tướng.':room.phase==='battle'?'Trình chiếu trực tiếp · Chuyển góc nhìn bên dưới.':'Duyệt đủ 5 người mỗi đội, sau đó mở chọn tướng.';
 if(qrCode!==room.code){qrCode=room.code;QRCode.toCanvas($('#qr'),location.origin+'/player.html?room='+room.code,{width:100,margin:1,color:{dark:'#684773',light:'#fff9f0'}}).catch(()=>toast('Không tạo được QR. Bạn vẫn có thể dùng mã phòng.'));}
 updateHostScores();
}
function updateHostScores(){if(!room)return;const pair=nextPair(),ss=match?scores(match):[];$('#hostScores').innerHTML=pair.map(t=>{const s=ss.find(s=>s.team===t);return`<div><h3>${esc(room.teams[t])}</h3><p><span>⚔ Chiến đấu <b>${s?.kills||0}</b></span><span>▤ Kiến thức <b>${s?.knowledge||0}</b></span></p></div>`;}).join('');}
bind('createRoom',async()=>{if(!auth)await session('Quản trò',true);room=await api('/api/rooms',{title:'Giải đấu MILA khanitta'});$('#teamEditors').innerHTML='';match=null;await connect(room.code);await loadRooms();toast('Đã tạo phòng '+room.code);});
async function loadRooms(){const list=await api('/api/rooms');$('#oldRooms').innerHTML='<option value="">Mở phòng đã tạo…</option>'+list.map(r=>`<option value="${r.code}">${r.code} · ${esc(r.title)}</option>`).join('');}
$('#oldRooms').addEventListener('change',run(async e=>{if(!e.target.value)return;$('#teamEditors').innerHTML='';match=null;await connect(e.target.value);}));
bind('copyInvite',async()=>{if(!room)throw Error('Tạo phòng trước nhé.');await navigator.clipboard.writeText(location.origin+'/player.html?room='+room.code);toast('Đã sao chép link cho học sinh.');});
bind('saveTeams',async()=>{const names=[...room.teams];for(const i of $$('[data-team-name]'))names[+i.dataset.teamName]=i.value.trim();if(names.some(n=>!n))throw Error('Nhập tên cho cả 4 đội.');await emit('mc',{action:'setup',teams:names});toast('Đã lưu tên các đội.');});
bind('hostStart',async()=>{await emit('mc',{action:room?.phase==='ready'?'launch':'start'});});
bind('pause',()=>emit('mc',{action:'pause'}));bind('endMatch',()=>modal('<h2>Kết thúc trận?</h2><p>Trận sẽ chốt điểm hiện tại và lưu kết quả.</p><button id="confirmEnd" class="primary">Kết thúc & lưu điểm</button>'));
document.addEventListener('click',run(async e=>{if(e.target.id==='confirmEnd'){await emit('mc',{action:'finish'});closeModal();toast('Đã lưu kết quả trận.');}}));
bind('addBots',async()=>{await emit('mc',{action:'bots'});toast('Đã điền người máy vào chỗ trống.');});
bind('members',()=>{if(!room)throw Error('Tạo phòng trước.');modal('<h2>Thành viên & duyệt vào phòng</h2><p>Duyệt người vào phòng và đặt danh sách tên cho từng đội.</p>'+room.teams.map((t,i)=>`<h3>${esc(t)}</h3><div class="team-people">${Array.from({length:5},(_,j)=>{const p=room.players.filter(p=>p.team===i)[j],row=room.roster?.filter(p=>p.team===i)[j];return`<label><input data-roster-team="${i}" data-roster-id="${row?.id||''}" placeholder="Thành viên ${j+1}" value="${esc(row?.name||p?.rosterName||p?.name||'')}">${p?`<small>${esc(p.name)} · ${p.approved?'✓ Đã duyệt':`<button data-approve="${p.id}">Duyệt</button>`}</small>`:''}</label>`;}).join('')}</div>`).join('')+'<button id="saveRoster" class="primary">Lưu danh sách tên</button>');});
