bind('shop',()=>modal('<h2>Cửa hàng phép thuật</h2><p>Dùng điểm kiến thức cá nhân. Mỗi món được mua một lần trong trận.</p><div class="button-row"><button data-buy="power">✦ Sức mạnh +5<br>200 điểm</button><button data-buy="shield">♢ Lá chắn +80<br>200 điểm</button></div>'));
