function renderResult(){show('result');const out=room.results.at(-1),pair=out.pair||room.pair;$('#result').innerHTML=`<div class="cup">🏆</div><small>HỌC VIỆN MILA khanitta</small><h2>${out.winner===null?'HAI ĐỘI HÒA ĐIỂM':esc(room.teams[out.winner])+' CHIẾN THẮNG!'}</h2><p>MVP: <b>${esc(out.mvp||'—')}</b></p><table><tr><th>Đội</th><th>Chiến đấu</th><th>Kiến thức</th><th>Tổng (50/50)</th></tr>${out.scores.map(s=>`<tr><td>${esc(room.teams[s.team])}</td><td>${s.kills} hạ gục</td><td>${s.knowledge}</td><td>${s.total.toFixed(1)}</td></tr>`).join('')}</table><p>${practice?'Bạn có thể luyện tập lại hoặc về học viện.':isVersus(room.mode)?'Trận đấu kết thúc · Về học viện để tạo phòng mới.':'Chờ quản trò mở vòng tiếp theo.'}</p><button id="backAcademy">Về học viện</button>`;$('#backAcademy').onclick=()=>location.href='/trial/index.html?mode='+playMode;if(practice)$('#result').insertAdjacentHTML('beforeend','<div class="button-row trial-result-actions"><button id="trialReplay">Chơi lại · chọn tướng</button><button id="trialExcel">Tải Excel</button><button id="trialPrint">In / lưu PDF</button><button id="trialHistory">Lịch sử thử</button></div>');}
