async function startPractice(){socket?.disconnect();practice=true;const bank=await import('./shared/questions.js');practiceBank=trialBankOverride||bank.questions;auth={id:'practice',name:$('#nickname').value.trim()||'Bông'};localStorage.setItem('mila-trial-name',auth.name);match=null;quiz=null;quizClosed=0;teamChat=[];keys.clear();pressed.clear();$('#quiz').hidden=true;$('#heroDetail').hidden=true;closeModal();room=createTrialRoom({name:auth.name,mode:playMode,team:Number($('#joinTeam').value)||0,...trialSettings});buildHeroGrid();selected='luna';$('#connection').textContent='● PHÒNG THỬ · NGƯỜI MÁY';$('#selectTime').textContent='20';updateRoom(room);}
async function launchPractice(){void enterMobileLandscape();practiceBank=trialBankOverride||(await import('./shared/questions.js')).questions;launchTrial(room);match=createMatch(room.players,room.pair,room.duration);cameraMode='follow';arena.camera('follow');$('#battle').classList.remove('spectator');$('#heroDetail').hidden=true;closeModal();quiz=null;simulationDebt=0;prevTick=performance.now();updateRoom(room);hudAt=0;updateMatch(match);if(musicEnabled){music.src='/assets/audio/chien-dau.ogg';music.play().catch(()=>{});}toast('Tay trái di chuyển · Tay phải tung chiêu. Hạ đối thủ để lên cấp!');}
function finishPractice(){if(!match||room.phase!=='battle')return;match.done=true;room.paused=false;room.phase='result';room.results=[{...matchResult(match),pair:match.pair,players:match.players.map(p=>({id:p.id,name:p.name,hero:p.hero,team:p.team,kills:p.kills,knowledge:p.knowledge,correct:p.correct})),at:new Date().toISOString()}];$('#quiz').hidden=true;quiz=null;try{const history=JSON.parse(localStorage.getItem('mila-trial-history')||'[]');history.unshift({teams:room.teams,mode:room.mode,...room.results[0]});localStorage.setItem('mila-trial-history',JSON.stringify(history.slice(0,20)));}catch{toast('Không lưu được lịch sử trên trình duyệt này.');}renderResult();}

