bind('questionBank',async()=>{const bank=await api('/api/bank');modal('<h2>Ngân hàng câu hỏi</h2><p>Excel gồm các cột CauHoi, DapAn (TRUE/FALSE), Vong (0, 1, 2), DoKho, ChuDe.</p><input type="file" id="importBank" accept=".xlsx,.xls"><p id="bankMessage"></p><label>Lọc câu hỏi<input id="filterBank" placeholder="Nhập từ khóa…"></label><div id="bankRows"></div>');const render=q=>{$('#bankRows').innerHTML=bank.filter(b=>b.text.toLowerCase().includes(q.toLowerCase())).slice(0,60).map(b=>`<div class="bank-row"><p>${esc(b.text)}</p><small>Đáp án: ${b.answer?'Đúng':'Sai'} · Vòng ${b.round+1} · ${esc(b.difficulty)}</small>${b.owner===auth.id?`<button data-edit-q="${b.id}">Sửa</button>`:''}</div>`).join('');};render('');$('#filterBank').oninput=e=>render(e.target.value);$('#importBank').onchange=run(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('File tối đa 1 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let s='';for(const b of bytes)s+=String.fromCharCode(b);const out=await api('/api/import',{base64:btoa(s)});$('#bankMessage').textContent='Đã nhập '+out.count+' câu. Mở lại ngân hàng để xem.';});for(const b of $$('[data-edit-q]'))b.onclick=()=>{const q=bank.find(q=>q.id===b.dataset.editQ);modal(`<h2>Sửa câu hỏi</h2><textarea id="editQText">${esc(q.text)}</textarea><label>Đáp án<select id="editQAnswer"><option value="true" ${q.answer?'selected':''}>Đúng</option><option value="false" ${!q.answer?'selected':''}>Sai</option></select></label><button id="saveQ" class="primary">Lưu câu hỏi</button>`);$('#saveQ').onclick=run(async()=>{await api('/api/bank/'+q.id,{text:$('#editQText').value,answer:$('#editQAnswer').value==='true'},'PATCH');closeModal();toast('Đã lưu câu hỏi.');});};});
