arena.externalClock();let prevTick=performance.now(),lastSend=0,simulationDebt=0;document.addEventListener("visibilitychange",()=>{prevTick=performance.now();simulationDebt=0;});function gameFrame(now){const dt=Math.min(.05,(now-prevTick)/1000);prevTick=now;if(practice&&room?.phase==='battle'&&!room.paused){simulationDebt+=dt;while(simulationDebt>=1/120){for(const p of match.players)p.input=p.bot?botInput(match,p):input();step(match,1/120);simulationDebt-=1/120;}pumpQuizzes(match,practiceBank);const me=match.players.find(p=>p.id===auth.id);if(me.quiz&&!me.quiz.resolved)openQuiz(publicQuiz(me.quiz));for(const p of match.players)if(p.bot&&p.quiz&&!p.quiz.resolved&&match.time-p.quiz.at>2)answerQuiz(match,p,p.quiz.index,Math.random()<.7?p.quiz.answer:!p.quiz.answer);updateMatch(match);if(match.done)finishPractice();}else if(room?.phase==='battle'&&!isHost&&online&&now-lastSend>=50){lastSend=now;socket?.emit('input',input());}arena.render(now);requestAnimationFrame(gameFrame);}requestAnimationFrame(gameFrame);
