async function init(){if(isHost){$('#observerMount').append($('#battle'));$('#battle').hidden=false;$('#battle').classList.add('spectator');show('host');$('#battle').hidden=false;arena.camera('overview');const ps=heroes.slice(0,5).map((h,i)=>({id:h.id,name:h.name,hero:h.id,slot:i,team:i<3?0:1}));const preview=createMatch(ps,[0,1],420);preview.players.forEach((p,i)=>{p.x=(i-2)*3;p.z=i%2?2:-2;});arena.snapshot(preview,null);await session('Quản trò',true);await loadRooms();const saved=JSON.parse(sessionStorage.getItem('mila-host-room')||'null');if(saved)await connect(saved.code);}
 else{show('entry');if($('#roomCode').value)await findRoom();const saved=JSON.parse(sessionStorage.getItem('mila-player-room')||'null'),old=JSON.parse(localStorage.getItem('mila-player')||'null');if(!trialMode&&saved&&(saved.mode===playMode)&&old?.token&&(!new URLSearchParams(location.search).get('room')||new URLSearchParams(location.search).get('room')===saved.code)){auth=old;await connect(saved.code,saved.team,saved.spectator);}}}
