init().catch(e=>toast(e.message));
bind('adjustScores',()=>{if(!room||!match)throw Error('Chưa có trận đấu để chỉnh điểm.');modal(`<h2>Chỉnh điểm kiến thức</h2><label>Học sinh<select id="adjustPlayer">${match.players.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${p.knowledge} điểm</option>`).join('')}</select></label><label>Điểm cộng / trừ<input type="number" id="adjustDelta" min="-1000" max="1000" value="0"></label><label>Lý do<input id="adjustReason" maxlength="200" placeholder="Nhập lý do điều chỉnh"></label><button id="saveAdjustment" class="primary">Lưu điều chỉnh</button><h3 style="margin-top:24px">Lịch sử điều chỉnh</h3><table>${room.history.map(h=>`<tr><td>${esc(h.student)}</td><td>${h.delta>0?'+':''}${h.delta}</td><td>${esc(h.reason)}</td></tr>`).join('')||'<tr><td>Chưa có điều chỉnh</td></tr>'}</table>`);});
document.addEventListener('click',run(async e=>{if(e.target.id==='saveAdjustment'){await emit('mc',{action:'adjust',id:$('#adjustPlayer').value,delta:+$('#adjustDelta').value,reason:$('#adjustReason').value});closeModal();toast('Đã lưu điểm và lịch sử chỉnh sửa.');}}));
let teamChat=[];
function chatDialog(){modal('<h2>Trò chuyện đồng đội</h2><div id="chatMessages"></div><form id="chatForm"><input id="chatText" maxlength="120" placeholder="Nhắn cho đồng đội…"><button class="primary">Gửi</button></form><small>Tin nhắn được lọc từ ngữ và giới hạn 2 giây / lần.</small>');renderChat();$('#chatForm').onsubmit=run(async e=>{e.preventDefault();const text=$('#chatText').value.trim();if(!text)return;if(practice){teamChat=trialChat(room,auth.name,text);renderChat();}else await emit('chat',text);$('#chatText').value='';});}
function renderChat(){if($('#chatMessages'))$('#chatMessages').innerHTML=teamChat.map(c=>`<p><b>${esc(c.name)}:</b> ${esc(c.text)}</p>`).join('')||'<p>Chưa có tin nhắn.</p>';}
document.addEventListener('click',run(async e=>{if(e.target.id==='openTeamChat'){chatDialog();if(practice)$('#chatForm').nextElementSibling.textContent='Chat thử có lọc từ · Chỉ lưu tại máy bạn; người máy không đọc tin nhắn.';}}));

// Local equivalents for a bot rehearsal. No accounts, public room codes or fake visitors.
function trialControls(){const active=room?.phase==='battle',locked=active||room?.phase==='result';modal(`<h2>Quản trò thử</h2><p>Bạn điều khiển cả phần chuẩn bị và bắt đầu trận. Dữ liệu thử lưu trên trình duyệt này.</p>${active?`<div class="button-row"><button id="trialPause">${room.paused?'▷ Tiếp tục':'Ⅱ Tạm dừng'}</button><button id="trialFinish">Kết thúc & lưu kết quả</button><button id="trialAdjust">Chỉnh điểm kiến thức</button></div><div class="button-row"><button data-trial-camera="follow">Theo nhân vật</button><button data-trial-camera="overview">Toàn sân</button><button data-trial-camera="teamA">Xem đội 1</button><button data-trial-camera="teamB">Xem đội 2</button></div>`:''}<label>Tên đội 1<input id="trialTeamA" maxlength="24" value="${esc(trialSettings.teams[0])}" ${locked?'disabled':''}></label><label>Tên đội 2<input id="trialTeamB" maxlength="24" value="${esc(trialSettings.teams[1])}" ${locked?'disabled':''}></label><label>Thời gian trận (giây)<input id="trialDuration" type="number" min="60" max="1800" value="${trialSettings.duration}" ${locked?'disabled':''}></label>${room&&!locked?'<h3>Thành viên</h3>'+room.players.map(p=>`<label>${esc(room.teams[p.team])} · ${p.bot?'Máy':'Bạn'}<input data-trial-player="${p.id}" maxlength="24" value="${esc(p.name)}"></label>`).join(''):''}${!locked?'<button id="saveTrialSettings" class="primary">Lưu cấu hình</button>':''}<div class="button-row"><button id="trialBank">Ngân hàng câu hỏi</button><button id="trialHistory">Lịch sử thử</button>${match?'<button id="trialExcel">Tải Excel</button><button id="trialPrint">In / lưu PDF</button>':''}</div>`);}
function toggleTrialPause(){if(!practice||room?.phase!=='battle')throw Error('Hãy bắt đầu trận trước.');room.paused=!room.paused;keys.clear();pressed.clear();simulationDebt=0;prevTick=performance.now();hudAt=0;updateMatch(match);closeModal();$('#pauseBanner').textContent=room.paused?'Ⅱ ĐÃ TẠM DỪNG · Chạm để tiếp tục':'';}
$('#pauseBanner').addEventListener('click',()=>{if(practice&&room?.paused)toggleTrialPause();});
function report(){if(!match)throw Error('Chưa có trận đấu.');return{...matchResult(match),teams:room.teams,players:match.players,at:new Date().toISOString()};}
let xlsxReady;
function loadExcel(){if(window.XLSX)return Promise.resolve(window.XLSX);xlsxReady??=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/trial/vendor/xlsx.js';script.onload=()=>resolve(window.XLSX);script.onerror=()=>{xlsxReady=null;reject(Error('Chưa tải được công cụ Excel. Hãy thử lại.'));};document.head.append(script);});return xlsxReady;}
async function exportTrialExcel(){const out=report(),XLSX=await loadExcel(),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(out.players.map(p=>({BietDanh:p.name,Doi:out.teams[p.team],Tuong:hero(p.hero).name,HaGuc:p.kills,KienThuc:p.knowledge,SoCauDung:p.correct}))), 'Ket qua');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(out.scores.map(s=>({Doi:out.teams[s.team],ChienDau:s.combat,KienThuc:s.learning,Tong:s.total}))), 'Xep hang');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(room.history||[]),'Lich su chinh diem');XLSX.writeFile(wb,'MILA-choi-thu.xlsx');}
function printTrial(){const out=report(),w=window.open('','_blank');if(!w)throw Error('Trình duyệt chặn cửa sổ in. Cho phép cửa sổ bật lên để lưu PDF.');w.document.write('<!doctype html><html lang="vi"><meta charset="utf-8"><title>Kết quả chơi thử MILA</title><style>body{font:16px system-ui;padding:24px;color:#332a40}table{border-collapse:collapse;width:100%}td,th{padding:10px;border:1px solid #aaa;text-align:left}@media print{button{display:none}}</style><h1>MILA khanitta · Kết quả chơi thử</h1><p>'+esc(new Date(out.at).toLocaleString('vi-VN'))+'</p><table><tr><th>Biệt danh</th><th>Đội</th><th>Tướng</th><th>Hạ gục</th><th>Kiến thức</th></tr>'+out.players.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+esc(out.teams[p.team])+'</td><td>'+esc(hero(p.hero).name)+'</td><td>'+p.kills+'</td><td>'+p.knowledge+'</td></tr>').join('')+'</table><p>MVP: '+esc(out.mvp)+'</p><button onclick="window.print()">In / Lưu PDF</button></html>');w.document.close();w.focus();w.print();}
function trialHistory(){let rows=[];try{rows=JSON.parse(localStorage.getItem('mila-trial-history')||'[]');}catch{}modal('<h2>Lịch sử chơi thử</h2><p>Lưu tối đa 20 trận trên trình duyệt này.</p>'+rows.map(r=>`<div class="bank-row"><b>${esc(r.teams[0])} — ${esc(r.teams[1])}</b><p>${esc(new Date(r.at).toLocaleString('vi-VN'))} · ${r.mode==='duel'?'1 vs 1':'5 vs 5'}<br>${r.winner===null?'Hòa':esc(r.teams[r.winner])+' thắng'} · MVP: ${esc(r.mvp)}</p></div>`).join('')+(rows.length?'':'<p>Chưa có trận hoàn thành.</p>'));}
async function trialBank(){const bank=trialBankOverride||(await import('./shared/questions.js')).questions,locked=room?.phase==='battle';modal('<h2>Ngân hàng câu hỏi thử</h2><p>'+bank.length+' câu · xáo trộn, không lặp trong cùng trận.</p>'+(!locked?'<p>Excel: cột <b>CauHoi</b> và <b>DapAn</b> (TRUE/FALSE).</p><input type="file" id="trialImport" accept=".xlsx,.xls"><div class="button-row"><button id="trialQuestionAdd">Thêm câu hỏi</button><button id="trialBankReset">Dùng 200 câu mặc định</button></div>':'<p>Kết thúc trận trước khi sửa ngân hàng.</p>')+'<label>Tìm câu hỏi<input id="trialQuestionSearch" placeholder="Nhập từ khóa"></label><div id="trialQuestionList"></div>');const draw=()=>{$('#trialQuestionList').innerHTML=bank.map((q,i)=>({...q,index:i})).filter(q=>q.text.toLowerCase().includes($('#trialQuestionSearch').value.toLowerCase())).slice(0,40).map(q=>`<div class="bank-row"><p>${esc(q.text)}</p><b>${q.answer?'Đúng':'Sai'}</b> ${locked?'':`<button data-edit-trial-q="${q.index}">Sửa</button>`}</div>`).join('');};draw();$('#trialQuestionSearch').oninput=draw;if(!locked)$('#trialImport').onchange=run(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>1000000)throw Error('File Excel tối đa 1 MB.');const X=await loadExcel(),book=X.read(await file.arrayBuffer(),{type:'array'}),rows=X.utils.sheet_to_json(book.Sheets[book.SheetNames[0]]);trialBankOverride=parseTrialQuestions(rows);localStorage.setItem('mila-trial-bank',JSON.stringify(trialBankOverride));toast('Đã nhập '+trialBankOverride.length+' câu.');await trialBank();});}
async function editTrialQuestion(index){const bank=trialBankOverride||(await import('./shared/questions.js')).questions,q=index===null?null:bank[index];modal(`<h2>${q?'Sửa':'Thêm'} câu hỏi</h2><textarea id="trialQuestionText" maxlength="500">${esc(q?.text||'')}</textarea><label>Đáp án<select id="trialQuestionAnswer"><option value="true" ${q?.answer!==false?'selected':''}>Đúng</option><option value="false" ${q?.answer===false?'selected':''}>Sai</option></select></label><button id="saveTrialQuestion" class="primary">Lưu</button>`);$('#saveTrialQuestion').onclick=run(async()=>{const rows=bank.map(q=>({...q})),item={text:$('#trialQuestionText').value,answer:$('#trialQuestionAnswer').value==='true'};if(index===null)rows.push(item);else rows[index]=item;trialBankOverride=parseTrialQuestions(rows);localStorage.setItem('mila-trial-bank',JSON.stringify(trialBankOverride));await trialBank();});}
document.addEventListener('click',run(async e=>{const id=e.target.closest('button')?.id;
 if(id==='trialControl'||id==='trialControlModal')trialControls();
 if(id==='trialPause')toggleTrialPause();
 if(id==='trialFinish'){finishPractice();closeModal();}
 if(id==='trialReplay')await startPractice();
 if(id==='trialHistory')trialHistory();
 if(id==='trialExcel')await exportTrialExcel();
 if(id==='trialPrint')printTrial();
 if(id==='trialBank')await trialBank();
 if(id==='trialQuestionAdd')await editTrialQuestion(null);
 if(e.target.closest('[data-edit-trial-q]'))await editTrialQuestion(+e.target.closest('[data-edit-trial-q]').dataset.editTrialQ);
 if(id==='trialBankReset'){trialBankOverride=null;localStorage.removeItem('mila-trial-bank');await trialBank();}
 if(id==='saveTrialSettings'){const teams=[$('#trialTeamA').value.trim(),$('#trialTeamB').value.trim()],duration=Number($('#trialDuration').value);if(teams.some(t=>!t)||!Number.isInteger(duration)||duration<60||duration>1800)throw Error('Nhập tên hai đội và thời gian từ 60–1800 giây.');const names=$$('[data-trial-player]').map(i=>i.value.trim());if(names.some(n=>!n)||new Set(names.map(n=>n.toLowerCase())).size!==names.length)throw Error('Tên thành viên không được trống hoặc trùng nhau.');trialSettings={teams,duration};localStorage.setItem('mila-trial-settings',JSON.stringify(trialSettings));if(room){room.teams.splice(0,2,...teams);room.duration=duration;for(const i of $$('[data-trial-player]')){const p=room.players.find(p=>p.id===i.dataset.trialPlayer);p.name=i.value.trim();if(!p.bot)auth.name=p.name;}}const selectedTeam=$('#joinTeam').value;$('#joinTeam').innerHTML=teams.map((t,i)=>`<option value="${i}">${esc(t)}</option>`).join('');$('#joinTeam').value=selectedTeam;closeModal();if(room)updateRoom(room);toast('Đã lưu cấu hình bản thử.');}
 const cam=e.target.closest('[data-trial-camera]');if(cam){const mode=cam.dataset.trialCamera;cameraMode=mode;arena.camera(mode.startsWith('team')?'team':mode,mode==='teamB'?1:0);closeModal();}
 if(id==='trialAdjust'){modal('<h2>Chỉnh điểm kiến thức thử</h2><select id="trialAdjustPlayer">'+match.players.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')+'</select><label>Điểm cộng / trừ<input type="number" min="-1000" max="1000" id="trialAdjustDelta" value="0"></label><label>Lý do<input id="trialAdjustReason" maxlength="200"></label><button id="saveTrialAdjustment">Lưu điều chỉnh</button><h3>Lịch sử chỉnh điểm</h3>'+room.history.map(h=>`<p>${esc(h.student)}: ${h.delta} · ${esc(h.reason)}</p>`).join(''));}
 if(id==='saveTrialAdjustment'){const p=match.players.find(p=>p.id===$('#trialAdjustPlayer').value),delta=Number($('#trialAdjustDelta').value),reason=$('#trialAdjustReason').value.trim();if(!p||!Number.isFinite(delta)||Math.abs(delta)>1000||!reason)throw Error('Nhập điểm ±1000 và lý do.');p.knowledge=Math.max(0,p.knowledge+delta);room.history.push({at:new Date().toISOString(),student:p.name,delta,reason});hudAt=0;updateMatch(match);closeModal();toast('Đã chỉnh điểm và lưu lịch sử thử.');}
}));
const modelLink=$('#modelRoomLink');modelLink.removeAttribute('style');modelLink.className='trial-model-link';$('.header-actions').prepend(modelLink);const controlButton=document.createElement('button');controlButton.id='trialControl';controlButton.textContent='Quản trò thử';$('.header-actions').prepend(controlButton);const historyButton=document.createElement('button');historyButton.id='trialHistory';historyButton.textContent='Lịch sử thử';$('.entry-links').append(historyButton);$('#nickname').value=localStorage.getItem('mila-trial-name')||$('#nickname').value;

$('#previewArt').addEventListener('click',()=>detail(own()?.heroReady?own().hero:selected));
